import{_ as i,l as o,o as e,c as s,v as r,p as n,x as l,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"难度课程","description":"","frontmatter":{"title":"难度课程","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rl-difficulty-curriculum.md","filePath":"llm/rl-difficulty-curriculum.md","lastUpdated":1789023840000}'),m={name:"llm/rl-difficulty-curriculum.md"};function u(h,a,E,_,f,A){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="难度课程" tabindex="-1">难度课程 <a class="header-anchor" href="#难度课程" aria-label="Permalink to &quot;难度课程&quot;">​</a></h1><div class="epigraph"><p>先让相对优势存在，再把题变难：课程改的是提示分布，不是学习率表。</p><footer>—— 对照 MATH 的难度分级；Open-Reasoner-Zero / 竞赛题课程；动态采样按通过率过滤的即时课程</footer></div><p><a href="/llm/rl-sampling-temperature">上一课</a>用温度制造组内分叉。题太难时，升温也全错；太易则全对。缺口是：<strong>提示分布本身要随策略能力移动，使组内经常落在 0–1 之间。</strong> 本课写预设难度课程，并对照 <a href="/llm/dynamic-sampling-rl">动态采样</a> 的在线过滤。接到 <a href="/llm/grpo">GRPO</a> 与 <a href="/llm/verifiable-reward">可验证奖励</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>MATH 有 1–5 级，竞赛题有年份与分区。从 5 级开训，G 条全 0，无梯度。只训 1 级，策略不会迁移到竞赛。课程：按准确率或人工级，把 \\(p(x)\\) 从易调到难。Kimi k1.5、若干开源数学 RL 配方都描述过由易到难或按通过率混合。这与 SFT 的 instruction curriculum 不同：RL 的信号是相对对错，课程的目标是<strong>保持中间通过率</strong>，不是先模仿简单示范。</p><p>动态采样是瞬时过滤；课程是先验混合。两者叠加：课程保证池子里有边界题，动态采样再丢掉当前全 0/1。只有动态、池子全是地狱题，会采不满。只有课程、不动态，后期易题仍浪费。</p><h3 id="难度标签会过期" tabindex="-1">难度标签会过期 <a class="header-anchor" href="#难度标签会过期" aria-label="Permalink to &quot;难度标签会过期&quot;">​</a></h3><p>人工「5 级」对基座难，对训了十万步的策略可能已是 1 级。课程应按<strong>当前策略的通过率</strong>重打标签，而不是永远信题面星级。否则名为课程，实为固定混合。</p><p><span class="marginnote">不要用 RM 分数当难度。RM 爱长、爱格式，会把啰嗦题标成难。可验证域用经验通过率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>离线：按基座 pass@G 分桶，训练按时间提高难题比例。在线：周期性用当前 \\(\\pi\\) 估通过率，重分桶。混合不要阶跃切掉易题——遗忘已会的格式与简单技巧。保留一小份易题当锚。代码域按测例数或算法标签分桶，同样用通过率校准。</p>',11)),(e(),n(c,null,{default:l(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20POOL%5B%22%E9%A2%98%E5%BA%93%22%5D%20--%3E%20TAG%5B%22%E6%8C%89%E5%BD%93%E5%89%8D%E9%80%9A%E8%BF%87%E7%8E%87%E5%88%86%E6%A1%B6%22%5D%0A%20%20TAG%20--%3E%20MIX%5B%22%E8%AF%BE%E7%A8%8B%E6%B7%B7%E5%90%88%20p(x)%22%5D%0A%20%20MIX%20--%3E%20G%5B%22%E7%BB%84%E9%87%87%E6%A0%B7%22%5D%0A%20%20G%20--%3E%20DYN%5B%22%E5%8A%A8%E6%80%81%E9%87%87%E6%A0%B7%E6%BB%A4%200%2F1%22%5D%0A%20%20DYN%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%20%CF%80%22%5D%0A%20%20UPD%20--%3E%20TAG%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>评测集冻结、不进课程重标，防止把评测题训穿。课程只作用于训练提示。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中间通过率使 \\(\\mathrm{std}(\\{r_i\\})\\) 经常非零，优势有信号。课程比盲目加大 \\(G\\) 便宜：加大 \\(G\\) 在全错题上只是多浪费生成。副作用是分布偏移：训练提示的难度轮廓 ≠ 评测，需要在各桶都报准确率，避免只在课程重心上好看。</p><p><span class="marginnote">突然注入超难题会造成熵塌：模型学会「这题放弃，写最短错误格式」。应缓增。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>开放偏好没有通过率，难度难定义，本课主场仍是数学 / 代码。多目标时「难」可能是更不安全的提示，课程会与安全硬门冲突，应分通道。下一课精度不匹配：课程与温度都对齐了，数值误差仍能把 \\(\\pi_{\\mathrm{beh}}\\) 弄错。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>难度课程调节提示分布，目标是维持中间通过率，让组相对优势存在。</li><li>星级会过期，应用当前策略通过率重标。</li><li>与动态采样互补：一个改池，一个滤组。</li><li>评测集冻结；各难度桶分别报告。</li><li>出处：Hendrycks MATH 分级；开源推理 RL 配方的由易到难混合；Yu 等动态采样作对照。</li></ul>',8))])}const b=i(m,[["render",u]]);export{T as __pageData,b as default};
